import jet.collections.{Set, Deque}

fn bfs(graph: Map<str, [str]>, start: str) -> [str] {
  let visited = Set.new()
  let queue   = Deque.new()
  queue.push_back(start)
  while let Some(node) = queue.pop_front() {
    if visited.insert(node) {
      for neighbor in graph.get(node).unwrap_or([]) {
        queue.push_back(neighbor)
      }
    }
  }
  visited.to_list()
}

